internal class GUPPriceEngineJournalLineObject
{

    PriceDiscTable priceDiscTable;
    
    GUPPriceEngineAttributeGroupObject headerAttributeGroup;
    GUPPriceEngineAttributeGroupObject lineAttributeGroup;

    // Indicate priority among compete journal lines. (i.e. lines with exactly same header and line attributes).
    // Within such lines, we must use the one with highest priority.
    // If two journal lines are not competing, the priority between them are meaningless.
    // When comparing, check from smallest to largest index, and the one with first larger int has a larger priority.
    Array attributesPriority;

    // An unique key refers to all attributes within the journal line.
    // If (and only if) two lines contain same attributes in same order, they should have the same key.
    // Lines with same group key are considered as 'compete journal lines'.
    str attributeGroupKey; 


}

Method.Source:
public void new(PriceDiscTable _journalLine, GUPPriceEngineAttributeGroupObject _headerAttributeGroup, GUPPriceEngineAttributeGroupObject _lineAttributeGroup)
{
    // Make a copy by the cursor.
    this.priceDiscTable = _journalLine.data();
    this.headerAttributeGroup = _headerAttributeGroup;
    this.lineAttributeGroup = _lineAttributeGroup;
    
    this.initializeGroupKeyAndAttributesPriority();
}

    /// <summary>
    /// Initialize attribute group key and attributes priority.
    /// </summary>
    public void initializeGroupKeyAndAttributesPriority()
    {
        str attributeKey = "attr_";

        // Header priority is more important than line priority.
        attributeKey = this.appendLineAttributesKey(headerAttributeGroup, attributeKey);
        attributeKey = this.appendLineAttributesKey(lineAttributeGroup, attributeKey);
        this.attributeGroupKey = attributeKey;

        int _index = 1;
        attributesPriority = new Array(Types::Integer);
        _index = this.computeLinePriority(_index, headerAttributeGroup, attributesPriority);
        this.computeLinePriority(_index, lineAttributeGroup, attributesPriority);
    }

private int computeLinePriority(int _index,
    GUPPriceEngineAttributeGroupObject _attributeGroup, 
    Array _priority)
{
    
    if (_attributeGroup != null)
    {
        ListEnumerator listEnumerator = _attributeGroup.parmAttributeConditionValueList().getEnumerator();
        while (listEnumerator.moveNext())
        {
            GUPPriceEngineConditionValueObject conditionValue = listEnumerator.current();
            _priority.value(_index, conditionValue.parmAttributePriority());
            _index ++;
        }
    }
    return _index;
}

    private int64 accumulateLinePriority(GUPPriceEngineAttributeGroupObject _attributeGroup, int64 _priority)
    {
        // Deprecated.
        if (_attributeGroup == null)
        {
            return _priority;
        }

        ListEnumerator listEnumerator = _attributeGroup.parmAttributeConditionValueList().getEnumerator();
        while (listEnumerator.moveNext())
        {
            GUPPriceEngineConditionValueObject conditionValue = listEnumerator.current();
            if (conditionValue.parmConditionValue() != "")
            {
                _priority += 1;
            }
            _priority = _priority << 1;
        }
        return _priority;
    }

    private str appendLineAttributesKey(GUPPriceEngineAttributeGroupObject _attributeGroup, str _attributeKey)
    {
        if (_attributeGroup == null)
        {
            return _attributeKey + "ALL_";
        }

        // Append group id: assume compete line must have SAME header and line group.
        _attributeKey = _attributeKey + int642Str(_attributeGroup.parmPricingAttributeGroup().RecId) + "#";

        // Compute hash of all attribute under the header / line group.
        System.Text.StringBuilder sBuilder = new System.Text.StringBuilder();
        ListEnumerator listEnumerator = _attributeGroup.parmAttributeConditionValueList().getEnumerator();
        while (listEnumerator.moveNext())
        {
            GUPPriceEngineConditionValueObject conditionValue = listEnumerator.current();
            sBuilder.Append(this.generateAttributeKey(conditionValue));
        }
        _attributeKey = _attributeKey + GUPHashHelper::getMD5StringHash(sBuilder.ToString());

        return _attributeKey + "_";
    }

    private str generateAttributeKey(GUPPriceEngineConditionValueObject _conditionValue)
    {
        GUPPricingAttributeLink link = _conditionValue.parmAttributeLink();

        // Class based attribute are distinct by class id.
        if (link.AttributeProviderClassId == 0)
        {
            return int642Str(link.PriceAttributeClassId);
        }
        // EcoResAttribute are distinct by name + type name.
        else
        {
            return link.AttributeName + ":" + link.TypeName;
        }

    }
